export function summarize(text, { since } = {}) {
  let cutoff = null;
  if (since !== undefined && since !== null) {
    cutoff = since instanceof Date ? since.getTime() : Date.parse(since);
    if (Number.isNaN(cutoff)) throw new Error(`invalid --since date: ${since}`);
  }
  const levels = {};
  const times = [];
  for (const line of text.split(/\r?\n/)) {
    if (!line.trim()) continue;
    const event = JSON.parse(line);
    if (cutoff !== null) {
      if (!event.time) continue;
      const t = Date.parse(event.time);
      if (Number.isNaN(t) || t < cutoff) continue;
    }
    levels[event.level] = (levels[event.level] ?? 0) + 1;
    if (event.time) times.push(event.time);
  }
  times.sort();
  return { levels, first: times[0] ?? null, last: times[times.length - 1] ?? null };
}
